function validateArgs(schema, args) {
  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    throw new Error('Arguments must be an object');
  }
  // check required
  for (const r of schema.required) {
    if (!(r in args)) throw new Error(`Missing argument: ${r}`);
  }
  // check extra
  for (const k of Object.keys(args)) {
    if (!(k in schema.properties)) throw new Error(`Unknown argument: ${k}`);
  }
  // check types
  for (const [k, v] of Object.entries(args)) {
    const prop = schema.properties[k];
    if (prop.type === 'string' && typeof v !== 'string') {
      throw new Error(`Argument ${k} must be a string`);
    }
    if (prop.type === 'string' && prop.minLength !== undefined && v.length < prop.minLength) {
      throw new Error(`Argument ${k} must be non-empty`);
    }
  }
}

function ok(text) {
  return { content: [{ type: 'text', text: String(text) }] };
